const conferenceMode=new URLSearchParams(location.search).get('conference')==='1';
const saveKey=conferenceMode?'fjordsprint-conference-v1':'fjordsprint-v1';
const courseRevision='3.3';
document.body.classList.toggle('conference-mode',conferenceMode);
const director=new RaceDirector();
let leaderboard,localCupBoard,challenge=null,questionDeck,cupRun,stageTelemetry;
const stageNames=courses.map(course=>course.name);
const ROCKET_TIMELINE=13.2;
const flightDuration=()=>cupRun&&cupRun.stages.length<stageNames.length?8.8:ROCKET_TIMELINE;
const rocketAge=()=>Math.min(ROCKET_TIMELINE,finishAge*ROCKET_TIMELINE/flightDuration());
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
