const defaults={mobileHelp:touchDevice(),cup:true,volume:.3,music:true,quality:navigator.maxTouchPoints>0?'low':'high',coaching:true,autogas:false,livery:'#e6edf3',motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,assist:true,quiz:true,deck:0,ghost:true,ghostGoal:'personal',camera:'chase'};
let settings={...defaults,...saved.settings},records=saved.courseRevision===courseRevision&&saved.records&&typeof saved.records==='object'?saved.records:{},mode='menu',trackIndex=0,track,world,archive,car=initialState(),audio=new RaceAudio(),keys={},touch={},raceSettings={},countdown=3,lastCount=4,toastTimer=0,quizState=null,answers=[],recording=[],recordAt=0,ghostFrames=null,ghostIndex=0,ghostLabel='REKORDEN',modalReturn='menu',modalFocus=null,practiceIndex=0,padWas=[],lastFrame=performance.now(),accumulator=0,hudAccumulator=0;
const fixedStep=1/120;
if(conferenceMode)Object.assign(settings,conferenceSettings);

let progress=loadProgress(saved.progress,records),previousCar={...car},encounters=[],dodges=0,finishAge=0,hardArchive,mapCache=null;
